{
  "model": "{{model_primary}}",
  "messages": [
    {
      "role": "user",
      "content": "Explain an API gateway in one sentence."
    }
  ]
}

{
  "model": "{{model_primary}}",
  "messages": [
    {
      "role": "system",
      "content": "You are terse. Never exceed one sentence."
    },
    {
      "role": "user",
      "content": "What does a circuit breaker do?"
    },
    {
      "role": "assistant",
      "content": "It stops calling a provider that keeps failing."
    },
    {
      "role": "user",
      "content": "And when does it try again?"
    }
  ]
}

{
  "model": "{{model_primary}}",
  "messages": [
    {
      "role": "user",
      "content": "Suggest a name for a load balancer."
    }
  ],
  "n": 3
}

{
  "model": "{{model_primary}}",
  "messages": [
    {
      "role": "user",
      "content": "What is the weather in Lisbon?"
    }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "get_weather",
        "description": "Current weather for a city.",
        "parameters": {
          "type": "object",
          "properties": {
            "city": {
              "type": "string"
            }
          },
          "required": [
            "city"
          ]
        }
      }
    }
  ],
  "tool_choice": {
    "type": "function",
    "function": {
      "name": "get_weather"
    }
  }
}

{
  "model": "{{model_primary}}",
  "messages": [
    {
      "role": "user",
      "content": "Count from one to eight."
    }
  ],
  "stream": true,
  "stream_options": {
    "include_usage": true
  }
}

{
  "model": "{{model_primary}}",
  "messages": [
    {
      "role": "user",
      "content": "Could you lay out what the CAP theorem says? [run {{cache_nonce}}]"
    }
  ],
  "temperature": 0
}
